/** Listing, adding and editing the people on a sheet. */
@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record ListPeopleRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record AddPersonRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotBlank @Size(max = 200) String name, @NotNull @Pattern(regexp = "[ABC]") String grade) {
    }

    public record UpdatePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate gradeFrom, @NotNull Long version) {
    }

    public record RetirePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, LocalDate date) {
    }

    public record HoldPersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotNull Boolean held) {
    }

    public record AddPatronRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotNull Long patronId) {
    }

    public record PatronResponse(long personId, long patronId) {
    }

    /** One of a person's grades, from a from-date (null: from the beginning of time). */
    public record GradeResponse(LocalDate from, String grade) {
    }

    /** A person, with every grade recorded for them, the one from the beginning of time first. */
    public record PersonResponse(long id, String name, List<GradeResponse> grades, long version, boolean retired,
            LocalDate retiredFrom, boolean held) {
    }

    public static PersonResponse response(Person person) {
        List<GradeResponse> grades = person.getGrades().stream()
                .map(g -> new GradeResponse(g.getFromDate(), g.getGrade())).toList();
        return new PersonResponse(person.getId(), person.getName(), grades, person.getVersion(),
                person.isRetired(), person.getRetiredFrom(), person.isHeld());
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public List<PersonResponse> list(@Valid @RequestBody ListPeopleRequest req) {
        return service.list(req.sheet().trim()).stream().map(PersonController::response).toList();
    }

    @PostMapping("/add")
    public PersonResponse add(@Valid @RequestBody AddPersonRequest req) {
        return response(service.add(req.sheet().trim(), req.user().trim(), req.name().trim(), req.grade()));
    }

    @PostMapping("/update")
    public PersonResponse update(@Valid @RequestBody UpdatePersonRequest req) {
        return response(service.update(req.sheet().trim(), req.user().trim(), req.id(), req.version(), req.name().trim(),
                req.grade(), req.gradeFrom()));
    }

    @PostMapping("/retire")
    public PersonResponse retire(@Valid @RequestBody RetirePersonRequest req) {
        return response(service.retire(req.sheet().trim(), req.user().trim(), req.id(), req.date()));
    }

    @PostMapping("/hold")
    public PersonResponse hold(@Valid @RequestBody HoldPersonRequest req) {
        return response(service.hold(req.sheet().trim(), req.user().trim(), req.id(), req.held()));
    }

    @PostMapping("/patrons/list")
    public List<PatronResponse> patrons(@Valid @RequestBody ListPeopleRequest req) {
        return service.patrons(req.sheet().trim()).stream()
                .map(p -> new PatronResponse(p.getPersonId(), p.getPatronId())).toList();
    }

    @PostMapping("/patrons/add")
    public PatronResponse addPatron(@Valid @RequestBody AddPatronRequest req) {
        Patron added = service.addPatron(req.sheet().trim(), req.user().trim(), req.id(), req.patronId());
        return new PatronResponse(added.getPersonId(), added.getPatronId());
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and their grades (A, B or C), each from a from-date, and the date they are retired from, if any;
 * and whether they are on hold. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded, the first from the beginning of time (no from-date), the others each from a date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedGrade> grades = new ArrayList<>();

    /** Set once retired: the person counts as retired at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** While held, the person's OPEN claims count in no live total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** Bumped on every save; an edit must carry the version it was made from. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new DatedGrade(null, grade));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, the one from the beginning of time first and then by from-date. */
    public List<DatedGrade> getGrades() {
        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFromDate,
                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        String found = null;
        for (DatedGrade g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(date)) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /** Record the grade from a date, replacing any grade already recorded from that same date. */
    public void setGradeFrom(LocalDate fromDate, String grade) {
        grades.removeIf(g -> fromDate.equals(g.getFromDate()));
        grades.add(new DatedGrade(fromDate, grade));
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether a claim of this person in the given status counts toward the live totals. */
    public boolean counts(ClaimStatus status) {
        return status.counts() && !(held && status == ClaimStatus.OPEN);
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** One of a person's grades: in force from its from-date (none: from the beginning of time) until their next. */
@Embeddable
public class DatedGrade {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "grade", nullable = false)
    private String grade;

    protected DatedGrade() {
    }

    public DatedGrade(LocalDate fromDate, String grade) {
        this.fromDate = fromDate;
        this.grade = grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getGrade() {
        return grade;
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED); a DRAFT or OPEN claim
 * can be voided (VOID). A SETTLED or VOID claim cannot change status.
 */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Whether a claim in this status may move to the given one. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward the totals: only OPEN and SETTLED do. */
    public boolean counts() {
        return this == OPEN || this == SETTLED;
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing, adding, closing and reopening the periods on a sheet. */
@RestController
@RequestMapping("/api/periods")
public class PeriodController {

    public record ListPeriodsRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    /** A period's name has no spaces: it is written into the audit record as one field. */
    public record AddPeriodRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String name, @NotNull LocalDate from,
            @NotNull LocalDate to) {
    }

    public record ClosePeriodRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull Long id) {
    }

    /** closedDue is the due-total fixed when the period was closed; null while it is open. */
    public record PeriodResponse(long id, String name, LocalDate from, LocalDate to, boolean closed,
            String closedDue) {
    }

    private static PeriodResponse response(Period period) {
        return new PeriodResponse(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                period.isClosed(),
                period.getClosedDue() == null ? null
                        : period.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public List<PeriodResponse> list(@Valid @RequestBody ListPeriodsRequest req) {
        return service.list(req.sheet().trim()).stream().map(PeriodController::response).toList();
    }

    @PostMapping("/add")
    public PeriodResponse add(@Valid @RequestBody AddPeriodRequest req) {
        return response(service.add(req.sheet().trim(), req.user().trim(), req.name().trim(), req.from(), req.to()));
    }

    @PostMapping("/reopen")
    public PeriodResponse reopen(@Valid @RequestBody ClosePeriodRequest req) {
        return response(service.reopen(req.sheet().trim(), req.user().trim(), req.id()));
    }

    @PostMapping("/close")
    public PeriodResponse close(@Valid @RequestBody ClosePeriodRequest req) {
        return response(service.close(req.sheet().trim(), req.user().trim(), req.id()));
    }
}

import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, computed, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { AMOUNT, Claim, PersonClaims, cents, counts, money, overdue } from '../claims/claims';
import { DatedDue, Period, Periods } from '../periods/periods';
import { DatedGrade, Lateness, Rate, Rates, chargedDueCents, dueText, gradeOn, pctOn } from '../rates/rates';
import { Roles } from '../roles/roles';
import { Settings } from '../settings/settings';

// The people on the active sheet, in the order they were added, and the one form that both adds
// a person and edits an existing one (opening a person's editor fills the form with their values).
// A person's grade is dated: their first applies from the beginning of time, and each save records
// the form's grade from its from-date (the sheet's today when blank), keeping those recorded before;
// a save leaving the grade as the row shows it, with the from-date blank, records none. The row
// shows the grade in force on the sheet's today; each claim uses the one in force on its date.
// The editor remembers the version of the person it opened; if someone else has saved the person
// since, the save is refused and the form is refilled with the values the store holds now.
// Each row shows what the person has claimed and lists their claims; the sheet's claimed-total
// adds everyone's up. Only OPEN and SETTLED claims count toward any of these totals. Each claim shows
// what is due at the rate for the person's grade in force on the claim's date (a settled claim the
// figure fixed when settled), each person the sum of those figures over the claims that count, and
// the sheet's due-total adds up every person's due-total that has one. A live due is never below
// the sheet's floor (a figure fixed when settled, bound by a statement or by closing a period keeps its own).
// Taking a person's statement binds each of their claims that counts to the figure it has then
// (a stated claim shows and totals that figure); each row shows how many statements the person
// has taken, and the last one's due-total and date.
// Each claim shows the period its date falls in, and each period the due of the claims that count in it.
// A person can be retired from a date (the sheet's today when left blank); with a date set they count
// as retired at once, whatever the date. No claim of theirs can be dated after it. Retired people are
// left out of the list unless "show retired" is on; their claims keep counting in every total.
// A person can be put on hold and taken off it again: while held, their OPEN claims count in no
// total (their own, the sheet's or a period's); their SETTLED claims still do.
// The quick-add bar adds a DRAFT claim of an amount, dated the sheet's today with an empty note, for
// the person of a name, adding the person with grade A first when the name is not on the sheet.
// Each person, and the sheet, shows how many of the claims that count are overdue and the sum of
// their figures (the overdue-total). An overdue claim's figure has its late charge (the sheet's late
// percent of it for every full 30 days overdue) added on top, in every figure and total.
// A person can name other people on the sheet as their patrons, one at a time from their row (not
// themselves, and not the same person twice). Each row shows the person's patrons by name, sorted,
// and their backing: their patrons' due-totals added up, skipping those that are n/a.
interface Person {
  id: number;
  name: string;
  /** Every grade recorded for the person, the one from the beginning of time first. */
  grades: DatedGrade[];
  /** The version the store holds; an edit sends the version it was opened at. */
  version: number;
  retired: boolean;
  /** The date the person is retired from, or null. */
  retiredFrom: string | null;
  held: boolean;
}

/** Whether a claim of the person counts toward the totals: a held person's OPEN claims do not. */
function countsFor(p: Person | undefined, c: Claim): boolean {
  return counts(c) && !(p?.held && c.status === 'OPEN');
}

/** One of a person's patrons. */
interface PatronLink {
  personId: number;
  patronId: number;
}

/** A person's statements: how many, and the last one's due-total (n/a when it had none) and date. */
interface StatementSummary {
  personId: number;
  count: number;
  dueTotal: string;
  date: string;
}

/** A statement just taken, with the person's claims as it left them. */
interface StatementTaken {
  summary: StatementSummary;
  claims: Claim[];
}

/** What a quick-add made: the claim, and its person (`created` when added for it). */
interface QuickAdded {
  person: Person;
  created: boolean;
  claim: Claim;
}

